def solve(data):
    if not data['words']:
        return ""

    # Start with the first word as the initial prefix
    prefix = data['words'][0]

    # Compare the prefix with each subsequent word
    for word in data['words'][1:]:
        while not word.startswith(prefix):
            # If the current word does not start with the prefix, remove the last character from the prefix
            prefix = prefix[:-1]
            # If the prefix becomes empty, there is no common prefix
            if not prefix:
                return ""

    return prefix

