from typing import List

def solve(data: dict) -> str:
    if not data['words']:
        return ""

    # Find the shortest word to determine the possible length of the prefix
    min_word = min(data['words'], key=len)

    for i in range(len(min_word)):
        # Check if all words have the same character at this position
        if not all(word[i] == min_word[i] for word in data['words']):
            return min_word[:i]

    return min_word
